insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('338abc7b-47b0-4010-97a4-33947ef5f419', '392758af-001c-4dba-a27b-b64a1bfd7e56', $$inleiding: Pil&Pill brengt slaappil Metolani (Europees octrooi) op de markt via drogisterijen in Nederland en Duitsland$$,
   $$economie-havo-2018-i-slapend-rijk-worden-context1.png$$,
   $$De Nederlandse onderneming Pil&Pill (P&P) is van plan het product Metolani op de markt te brengen. Metolani is een pil om slaapproblemen te verhelpen. Het product is beschermd met een Europees octrooi. Metolani zal, zonder doktersrecept, uitsluitend verkrijgbaar zijn bij drogisterijen in Nederland en Duitsland. Drogisterijen in Nederland en Duitsland zijn vergelijkbare winkels.$$, 'inline'),
  ('998e6084-52be-47c2-b3ef-0ee8d68f7dea', '392758af-001c-4dba-a27b-b64a1bfd7e56', $$voorstel financieel manager: in Duitsland alleen variabele kosten terugverdienen, in Nederland maximale totale winst$$,
   $$economie-havo-2018-i-slapend-rijk-worden-context2.png$$,
   $$P&P wil Metolani in verpakkingen van duizend pillen aan de drogisterijen verkopen. Concurrenten van P&P bieden in Duitsland echter ook pillen met een vergelijkbare werking aan drogisterijen aan. Daarom stelt de financieel manager van P&P het volgende voor:
− Op de Duitse markt hoeven alleen de variabele kosten terugverdiend te worden, zodat we in Duitsland een lagere prijs kunnen vragen dan in Nederland. De vaste (constante) kosten (zie bron 1) zullen dan op de Nederlandse markt terugverdiend moeten worden.
− Op de Nederlandse markt vragen we een prijs waarbij er maximale totale winst wordt behaald.$$, 'inline'),
  ('8e627c8a-b65e-4d8e-9784-bcedc6158148', '392758af-001c-4dba-a27b-b64a1bfd7e56', $$reactie directeur: kunnen we prijsdiscriminatie toepassen?$$,
   $$economie-havo-2018-i-slapend-rijk-worden-context3.png$$,
   $$De directeur reageert op het voorstel van de financieel manager: “Ik vraag me af of we prijsdiscriminatie kunnen toepassen, omdat er dan voldaan moet worden aan bepaalde voorwaarden.”$$, 'inline'),
  ('dac6d923-9c36-42c5-9145-ad0caa086f7b', '392758af-001c-4dba-a27b-b64a1bfd7e56', $$Metolani mag alleen op doktersrecept bij apotheken worden verkocht$$,
   $$economie-havo-2018-i-slapend-rijk-worden-context4.png$$,
   $$Nog voordat Metolani wordt geïntroduceerd, blijkt volgens Europese richtlijnen dat de hoeveelheid werkzame stof per pil Metolani te hoog is om de pillen vrij te mogen verkopen bij drogisterijen. Er wordt besloten dat Metolani zowel in Nederland als in Duitsland uitsluitend op doktersrecept bij apotheken mag worden verkocht.$$, 'inline'),
  ('e420b348-9fe4-4767-bc02-a59e43f61e4a', '392758af-001c-4dba-a27b-b64a1bfd7e56', $$bron 1: kosten Metolani (constante en variabele kosten)$$,
   $$economie-havo-2018-i-slapend-rijk-worden-context5.png$$,
   $$bron 1 kosten Metolani
constante kosten:
− ontwikkelkosten € 20 miljoen
− management- & personeelskosten € 15 miljoen
− verzekeringspremies € 5 miljoen
− overige constante kosten € 17 miljoen
variabele kosten (proportioneel):
− per verpakking van 1.000 pillen € 50$$, 'inline'),
  ('d5d7e199-4506-4ba7-906f-80e803e99383', '392758af-001c-4dba-a27b-b64a1bfd7e56', $$bron 2: prijsafzet- en MO-functie Metolani op de Nederlandse markt$$,
   $$economie-havo-2018-i-slapend-rijk-worden-context6.png$$,
   $$bron 2 prijsafzet- en MO-functie Metolani van drogisterijen op de Nederlandse markt
P = −25Q + 230
MO = −50Q + 230
P (prijs) en MO (marginale opbrengsten) in euro’s per verpakking
P = prijs die de drogisterij betaalt aan de fabrikant
Q in miljoenen verpakkingen$$, 'inline'),
  ('63df7d5f-5f4f-40b1-b24f-69680898d260', '392758af-001c-4dba-a27b-b64a1bfd7e56', $$bron 3: vraaglijn Metolani van drogisterijen op de Duitse markt$$,
   $$economie-havo-2018-i-slapend-rijk-worden-context7.png$$,
   $$bron 3 vraaglijn Metolani van drogisterijen op de Duitse markt
grafiek: prijs per verpakking (€) (0-125) tegen hoeveelheid (in miljoenen verpakkingen) (0-11); rechte vraaglijn van € 100 bij hoeveelheid 0 naar prijs 0 bij hoeveelheid 10$$, 'inline'),
  ('4d75ce9f-f821-44e3-b0e7-4d0607b978fa', 'e7449000-540b-4c85-946e-cbaa372f397f', $$inleiding: gegevens uit de nationale rekeningen van Nederland in 2013$$,
   $$economie-havo-2018-i-van-nationaal-rekenen-naar-nationaal-beleid-context1.png$$,
   $$Gegevens uit de nationale rekeningen spelen een centrale rol bij het vaststellen van het economisch en monetair beleid. De economische groei, het overheidstekort en het nationaal spaarsaldo zijn belangrijke macro-economische indicatoren uit de nationale rekeningen. Bronnen 1, 2 en 3 zijn onderdelen uit de nationale rekeningen van Nederland in 2013.$$, 'inline'),
  ('3aa80cd1-30ff-4795-90e2-5fa7c2682ff1', 'e7449000-540b-4c85-946e-cbaa372f397f', $$bbp als maatstaf voor economische groei en welvaart$$,
   $$economie-havo-2018-i-van-nationaal-rekenen-naar-nationaal-beleid-context2.png$$,
   $$In de nationale rekeningen wordt het bruto binnenlands product (bbp) gebruikt om de economische groei te meten. Het bbp wordt ook vaak gebruikt om de welvaart te meten. Aan deze maatstaf kleven wel bezwaren, omdat sommige economische verschijnselen niet in het bbp zijn opgenomen. Dit kan betekenen dat de welvaart wordt onderschat of overschat.$$, 'inline'),
  ('7419ba75-7a97-457f-8e25-fdfbf35bf2d0', 'e7449000-540b-4c85-946e-cbaa372f397f', $$drie economische verschijnselen: negatieve externe effecten, zwarte circuit, vrijwilligerswerk$$,
   $$economie-havo-2018-i-van-nationaal-rekenen-naar-nationaal-beleid-context3.png$$,
   $$Hieronder staan drie economische verschijnselen.
1 negatieve externe effecten
2 productie in het zwarte circuit
3 vrijwilligerswerk$$, 'inline'),
  ('054dd3ad-101f-4bee-b627-8826a06c217e', 'e7449000-540b-4c85-946e-cbaa372f397f', $$de staat van middelen en bestedingen als geldkringloop (zie bron 3)$$,
   $$economie-havo-2018-i-van-nationaal-rekenen-naar-nationaal-beleid-context4.png$$,
   $$De staat van middelen en bestedingen kan ook worden weergegeven in een geldkringloop (zie bron 3).$$, 'inline'),
  ('f89fe0ff-de96-4365-bb9a-432ed5f61377', 'e7449000-540b-4c85-946e-cbaa372f397f', $$laag vertrouwen in 2013 en het Stabiliteitspact maken conjunctuurbeleid vrijwel onmogelijk$$,
   $$economie-havo-2018-i-van-nationaal-rekenen-naar-nationaal-beleid-context5.png$$,
   $$Als gevolg van de kredietcrisis en de daaropvolgende eurocrisis is het consumenten- en producentenvertrouwen in Nederland in 2013 laag. Dat uit zich in afnemende particuliere bestedingen (consumptie en investeringen), een toenemend nationaal spaaroverschot en een dalende inflatie. Een econoom stelt: “Op basis van deze gegevens zou de Nederlandse overheid er verstandig aan doen conjunctuurbeleid te voeren. Maar omdat Nederland zich moet houden aan het Stabiliteitspact van de Economische en Monetaire Unie (EMU), is conjunctuurbeleid vrijwel onmogelijk geworden.”$$, 'inline'),
  ('45c0cec2-9b86-4602-88fc-5d62e2a6703d', 'e7449000-540b-4c85-946e-cbaa372f397f', $$bron 1: macro-economische indicatoren Nederland, 2012 en 2013$$,
   $$economie-havo-2018-i-van-nationaal-rekenen-naar-nationaal-beleid-context6.png$$,
