   $$economie-havo-2018-i-van-nationaal-rekenen-naar-nationaal-beleid-vraag6.png$$, $$2p 6 Geef bij elk verschijnsel aan of het verschijnsel voor een onderschatting of een overschatting van de welvaart zorgt als deze gemeten wordt via het bbp.$$, array['4d75ce9f-f821-44e3-b0e7-4d0607b978fa', '3aa80cd1-30ff-4795-90e2-5fa7c2682ff1', '7419ba75-7a97-457f-8e25-fdfbf35bf2d0']::uuid[]),
